    if(type==='exploder'){x.fillStyle='#e8b23a';x.globalAlpha=0.85;x.fillRect(W*0.3,Hp*0.5,W*0.4,Hp*0.12);x.globalAlpha=1;}
    x.fillStyle=c2;
    if(atk){x.fillRect(0,Hp*0.5,W*0.24,Hp*0.06);x.fillRect(W*0.76,Hp*0.5,W*0.24,Hp*0.06);
      x.fillStyle=skin;x.fillRect(0,Hp*0.48,W*0.06,Hp*0.1);x.fillRect(W*0.94,Hp*0.48,W*0.06,Hp*0.1);}
