    const hw=W*0.34,hh=Hp*0.2,hx=(W-hw)/2,hy=Hp*0.2;
    x.fillStyle=skin;x.fillRect(hx,hy,hw,hh);
    x.fillStyle='#00000066';x.fillRect(hx,hy,hw,hh*0.32);
    x.fillStyle=type==='screamer'?'#d04040':'#c22';const ew=Math.max(1,hw*0.16);
    if(type==='screamer'){x.fillStyle='#000';x.fillRect(hx+hw*0.15,hy+hh*0.45,hw*0.7,hh*0.5);x.fillStyle='#a03030';x.fillRect(hx+hw*0.25,hy+hh*0.55,hw*0.5,hh*0.3);}
    else{x.fillRect(hx+hw*0.14,hy+hh*0.42,ew,hh*0.22);x.fillRect(hx+hw*0.7,hy+hh*0.42,ew,hh*0.22);}
    if(type==='stalker'){x.fillStyle='#00000055';x.fillRect(hx,hy,hw,hh);}
    for(let i=0;i<10;i++){x.fillStyle='rgba(120,20,20,0.5)';x.fillRect(hx+Math.random()*hw,hy+hh*0.3+Math.random()*hh*0.6,1,2);}
    return c;
  }
  const frames=[frame(0,0),frame(1,0),frame(2,0),frame(0,1),frame(2,1)];
