function updatePlayer(dt){
  const M=game.map;
  const aiming=held.aim;
  player.ads+=((aiming?1:0)-player.ads)*Math.min(1,dt*11);
  // crouch & slide
  const wantCrouch=held.crouch;
  if(wantCrouch&&!player.crouch&&player.slideT<=0&&movingFast())player.slideT=0.5;
  player.crouch=wantCrouch||player.slideT>0;
  if(player.slideT>0)player.slideT-=dt;
