  const sprint=held.sprint&&l>0.75&&!aiming&&!player.reloading;
  if(sprint)sp=5.3;
  if(player.crouch)sp*=0.55;
  if(player.ads>0.5)sp*=0.62;
  if(player.reloading&&WEAPONS[curW().w].c==='lmg')sp*=0.85;
  sp*=(0.75+0.25*(1-player.ads));
  const fx=Math.cos(player.a),fy=Math.sin(player.a);
  let dx=(fx*(-mvy)+fy*mvx)*sp*dt,dy=(fy*(-mvy)-fx*mvx)*sp*dt;
  if(player.slideT>0){dx*=1.9;dy*=1.9;}
  moveC(dx,dy);
  player.bob+=l*sp*dt*1.7;
  // look
  IN.pitch=clamp(pitchAcc,-70,70);player.pitch=IN.pitch;
  pitchAcc+=(-player.pitch)*Math.min(1,dt*8);player.pitch=IN.pitch;
