    if(player.reloadT<wRelTotal()*0.6&&!player._click){player._click=true;sfx('clickl');}
    if(player.reloadT<=0){const s=curW(),need=wMag()-s.mag,take=Math.min(need,s.res);
      s.mag+=take;s.res-=take;player.reloading=false;player._click=false;sfx('clikh');updateHUD();}}
  if(EDGE.swap&&player.slots[1-player.cur]){player.cur=1-player.cur;player.reloading=false;player.ammoIn=false;sfx('clikh');updateHUD();}
  if(EDGE.melee)melee();
  if(EDGE.nade)throwNade(vNadeFrag,0);
  player.meleeT=Math.max(0,player.meleeT-dt);
  // interaction
  doInteract(dt);
  // regen
  player.regenT+=dt;
  if(player.regenT>2.6&&player.hp<player.max){player.hp=Math.min(player.max,player.hp+42*dt);dmgVig(clamp(1-player.hp/player.max,0,0.5)*0.5);updateHUD();}
  // pickups
  for(let i=pickups.length-1;i>=0;i--){const p=pickups[i];p.t-=dt;
