      else if(p.k==='gun'){const old=giveWeapon(p.v);toast('�uman PICKED UP '+WEAPONS[p.v].n.toUpperCase().replace('UMAN ',''));sfx('egg');}
      pickups.splice(i,1);updateHUD();continue;}
    if(p.t<=0)pickups.splice(i,1);}
}
