    const dmg=wDmg()*fall*(c.head?2.2:1);
    damageZombie(c.z,dmg,rdx,rdy,c.head);
    left--;
  }
  if(!cands.length)parts.push({x:player.x+rdx*wd,y:player.y+rdy*wd,z:rnd(.35,.65),vx:rnd(-1,1),vy:rnd(-1,1),life:0.18,c:'#ccc',s:2});
}
function tryFire(dt){
  const s=curW();if(!s)return;const w=WEAPONS[s.w];
  if(player.reloading||player.meleeT>0.35)return;
  if(player.burstLeft>0){
    player.burstT-=dt;
    if(player.burstT<=0){player.burstT=0.06;player.burstLeft--;fireOne(s,w);}
    return;
  }
  if(!held.fire){player.ammoIn=false;return;}
  if(!w.auto&&player.ammoIn)return;
  if(player.fireT>0)return;
  if(s.mag<=0){sfx('deny',{v:0.4});lowAmmoToast();player.fireT=0.35;player.ammoIn=true;if(s.res>0)startReload();return;}
  player.ammoIn=!w.auto;
  if(w.burst){player.burstLeft=Math.min(w.burst,s.mag)-1;player.burstT=0.06;fireOne(s,w);return;}
  fireOne(s,w);
}
/* ---------------- GRENADES ---------------- */
function throwNade(){
  if(player.nades<=0){sfx('deny');return;}
  player.nades--;const v=PROJ.nade;
  nades.push({x:player.x+Math.cos(player.a)*0.4,y:player.y+Math.sin(player.a)*0.4,
    vx:Math.cos(player.a)*v.sp,vy:Math.sin(player.a)*v.sp,z:0.42,vz:1.3,gl:0,fuse:v.fuse,rad:v.rad,dmg:v.dmg,spin:0});
  updateHUD();
}
function updateNades(dt){
  const keep=[];
  for(const n of nades){
    n.fuse-=dt;n.spin+=dt*10;
    const nx=n.x+n.vx*dt,ny=n.y+n.vy*dt;
    if(hitWall(nx,n.y,0.09))n.vx*=-0.45;else n.x=nx;
    if(hitWall(n.x,ny,0.09))n.vy*=-0.45;else n.y=ny;
    n.vz-=5.5*dt;n.z+=n.vz*dt;
    if(n.z<0.06){n.z=0.06;n.vz=Math.abs(n.vz)*0.45;if(n.vz<0.35)n.vz=0;}
    if(n.fuse<=0)explode(n.x,n.y,n.rad,n.dmg);else keep.push(n);
  }
  nades=keep;
}

/* ---------------- PLAYER MOVEMENT ---------------- */
function movingFast(){return held.sprint||Math.hypot(IN.mvX,IN.mvY)>0.95;}
function hitWall(x,y,r){
  for(let yy=Math.floor(y-r);yy<=Math.floor(y+r+0.001);yy++)
    for(let xx=Math.floor(x-r);xx<=Math.floor(x+r+0.001);xx++)if(isWall(xx,yy))return true;
  return false;
}
function moveC(dx,dy){
  const r=player.crouch?0.26:0.3;
  if(!hitWall(player.x+dx,player.y,r))player.x+=dx;else if(!hitWall(player.x+dx*0.4,player.y,r))player.x+=dx*0.4;
  else if(Math.abs(dx)>small24()){/*blocked*/}
  if(!hitWall(player.x,player.y+dy,r))player.y+=dy;else if(!hitWall(player.x,player.y+dy*0.4,r))player.y+=dy*0.4;
  function small24(){return 0.001;}
}
function updatePlayer(dt){
  const aiming=held.aim;
  player.ads+=((aiming?1:0)-player.ads)*Math.min(1,dt*11);
  if(held.crouch&&!player.crouch&&player.slideT<=0&&movingFast()&&player.slideCd<=0){player.slideT=0.55;player.slideCd=1.2;}
  if(player.slideT>0)player.slideT-=dt;
  if(player.slideCd>0)player.slideCd-=dt;
  player.crouch=held.crouch||player.slideT>0.15;
  let mvx=IN.mvX,mvy=IN.mvY;const l=Math.hypot(mvx,mvy);
  let sp=2.95;if(hasPerk('sprint'))sp+=0.55;
  const sprint=held.sprint&&l>0.75&&!aiming&&!player.reloading;
  if(sprint)sp=5.35;
  if(player.crouch)sp*=0.55;
  if(player.ads>0.5)sp*=0.66;
  if(l>1){mvx/=l;mvy/=l;}
  const fx=Math.cos(player.a),fy=Math.sin(player.a);
  const dx=(fx*(-mvy))*sp*dt+(fy*mvx)*sp*dt;
  const dy=(fy*(-mvy))*sp*dt-(fx*mvx)*sp*dt;
  moveC(player.slideT>0?dx*1.85:dx,player.slideT>0?dy*1.85:dy);
  player.bob+=l*sp*dt*1.75;
  player.a=angN(player.a+IN.look);
  player.pitch=clamp(pitchAcc,-70,70)*1;pitchAcc=player.pitch;
  tryFire(dt);
  player.fireT=Math.max(0,player.fireT-dt);
  player.kick=Math.max(0,player.kick-dt*6);
  if(EDGE.reload)startReload();
  if(player.reloading){player.reloadT-=dt;
    if(player.reloadT<=wRelTime()*0.6&&!player._ck){player._ck=true;sfx('clickl');}
    if(player.reloadT<=0){const s=curW(),take=Math.min(wMag()-s.mag,s.res);
      s.mag+=take;s.res-=take;player.reloading=false;player._ck=false;sfx('clikh');updateHUD();}}
  if(EDGE.swap&&player.slots[1-player.cur]){player.cur=1-player.cur;player.reloading=false;player.ammoIn=false;sfx('clikh');updateHUD();}
  if(EDGE.melee)meleeAct();
  if(EDGE.nade)throwNade();
  player.meleeT=Math.max(0,player.meleeT-dt);
  doInteract(dt);
  player.regenT+=dt;
  if(player.regenT>2.6&&player.hp<player.max){player.hp=Math.min(player.max,player.hp+42*dt);
    dmgVig(clamp(1-player.hp/player.max,0,0.55)*0.5);updateHUD();}
  for(let i=pickups.length-1;i>=0;i--){const p=pickups[i];p.t-=dt;
    if(p.t<=0){pickups.splice(i,1);continue;}
    if(Math.hypot(p.x-player.x,p.y-player.y)<1.05){
      if(p.k==='ammo'){for(const s of player.slots)if(s)s.res=WEAPONS[s.w].res;toast('+ FULL RESERVE AMMO');sfx('buy');}
      else if(p.k==='pts'){givePoints(p.v);pop('+'+p.v);sfx('buy');}
      else if(p.k==='gun'){takePickupGun(p.v);}
      pickups.splice(i,1);updateHUD();
    }
  }
}
function takePickupGun(id){const s=player.slots.find(x=>x&&x.w===id);
  if(s){ammoRefillGun(id);toast('TOOK '+WEAPONS[id].n.toUpperCase()+' (AMMO)');}
  else{giveWeapon(id);toast('PICKED UP '+WEAPONS[id].n.toUpperCase());}
  sfx('buy');}
function ammoRefillGun(id){for(const s of player.slots)if(s&&s.w===id){s.res=WEAPONS[id].res;s.mag=wMagFull(id);}}
function startReload(){const s=curW();if(!s||player.reloading)return;
  if(s.mag>=wMag()||s.res<=0)return;
  player.reloading=true;player.reloadT=wRelTime();sfx('clickl');}
function meleeAct(){
  if(player.meleeT>0)return;player.meleeT=0.7;player.kick=1;rumble(90,0.6,0.4);sfx('clickl');
  for(const z of zombies){
    if(z.dead||z.knock>0||z.st!=='walk'&&z.st!=='attack')continue;
    const dx=z.x-player.x,dy=z.y-player.y,d=Math.hypot(dx,dy);
    if(d<1.5&&Math.abs(angN(Math.atan2(dy,dx)-player.a))<0.95){damageZombie(z,160,dx/d,dy/d,false);break;}
  }
}
/* ---------------- INTERACT (HOLD to buy like console CoD) ---------------- */
function nearestTarget(){
  let best=null,bd=9;const M=game.map;
  for(const w of M.buys){const d=Math.hypot(w.x-player.x,w.y-player.y);if(d<1.9&&d<bd){bd=d;best={k:'buy',o:w};}}
  for(const w of M.winW){const d=Math.hypot(w.x-player.x,w.y-player.y);if(d<1.75&&d<bd){bd=d;best={k:'repair',o:w};}}
  for(const p of M.perksA){const d=Math.hypot(p.x-player.x,p.y-player.y);if(d<1.9&&d<bd){bd=d;best={k:'perk',o:p};}}
  {const d=Math.hypot(M.forge.x-player.x,M.forge.y-player.y);if(d<2&&d<bd){bd=d;best={k:'forge'};}}
  {const d=Math.hypot(M.box.x-player.x,M.box.y-player.y);if(d<2.05&&d<bd){bd=d;best={k:'box'};}}
  for(const d of M.doorsA){if(d.open)continue;const dd=Math.hypot(d.px-player.x,d.py-player.y);if(dd<2&&dd<bd){bd=dd;best={k:'door',o:d};}}
  for(const g of M.eggsA){if(!g.dead){const gd=Math.hypot(g.x-player.x,g.y-player.y);if(gd<8&&gd<bd+4){best=best||{k:'egg',o:g};}}}
  {const d=Math.hypot(M.radio.x-player.x,M.radio.y-player.y);if(d<1.8&&d<bd){bd=d;best={k:'radio'};}}
  return best;
}
let holdT=0,holdDone=false;
function doInteract(dt){
  const t=nearestTarget();lastTarget=t;
  if(boxRoll.on&&boxRoll.done){
    if(held.interact&&!holdDone){takeRolled();holdDone=true;holdT=-99;}
    showPrompt(t);if(lastTarget&&lastTarget.k==='box'&&boxRoll.done)showPrompt({k:'roledge'});
    return;
  }
  if(t&&held.interact&&!holdDone){
    holdT+=dt;
    if(t.k==='repair'){
      if(holdT>0.45){const w=t.o;if(w.boards<w.max){w.boards++;w.hp=Math.max(w.hp,1);givePoints(10);sfx('repair');pop('+10');}holdT=0;holdDone=(w.boards>=w.max);}
    }else if(holdT>0.38){doAction(t);holdDone=true;}
  }else if(!held.interact){holdT=0;holdDone=false;}
  showPrompt(t);
}
function doAction(t){
  if(t.k==='buy')buyWall(t.o);
  else if(t.k==='perk')buyPerk(t.o);
  else if(t.k==='door')buyDoor(t.o);
  else if(t.k==='box')startBox();
  else if(t.k==='forge')forgeUp();
  else if(t.k==='radio')radioAct();
}
