  if(player.slots[0]&&player.slots[1]&&player.slots[0].w!==id&&player.slots[1].w!==id){
    const cur=player.slots[player.cur];
    const oldW=cur.w;game.points-=px;player.slots[player.cur]={w:id,mag:wMagFull(id),res:WEAPONS[id].res};
    givePoints(0);givePoints(-(0));game.points+=truckPts(px);player.reloading=false;sfx('buy');
    toast('BOUGHT '+WEAPONS[id].n.toUpperCase()+' (REPLACED '+WEAPONS[oldW].n.toUpperCase()+')');readerPop(-px);updateHUD();return id;}
  if(game.points>=px){game.points-=px;giveWeapon(id);sfx('buy');toast('BOUGHT '+WEAPONS[id].n.toUpperCase());updateHUD();return id;}
