/* ---------------- ROUNDS ---------------- */
function startRound(n){
  game.round=n;
  const r=n;
  game.toSpawn=Math.min(8+r*3,84);
  game.spawnT=game.phase==='boss'?0:0.8;
  game.phase='active';
  game.musicL=clamp((r-1)/22,0,1);musicLevel(game.musicL);
  const bossR=r%10===0,fiveR=r%5===0&&!bossR;
  if(bossR){showBanner('','');showBanner('⚠ WARNING ⚠','ROUND '+r);game.grid=0;}
  else showBanner('ROUND '+r,r===1?'ARE YOU READY?':(fiveR?'SPECIAL EVENT INCOMING':'THEY COME FOR YOU'));
  sfx('round');
  if(fiveR){
    const ev=[['FRENZY','Everything runs now'],['GAS DRAG',('Bloaters roam — keep your distance')],['BLACKOUT','Lights failing... watch the dark'],['NIGHTMARE','The dead are fast and armored']][ri(0,3)];
    game.event=ev[0];
    setTimeout(()=>showBanner('⚠ '+ev[0]+' ⚠',ev[1]),800);
  } else game.event=null;
  updateHUD(true);
}
function roundLogic(dt){
  if(game.phase==='idle'){game.phaseT-=dt;if(game.phaseT<=0)startRound(1);return;}
  if(game.phase==='intermission'){
    game.phaseT-=dt;
    if(game.phaseT<=0)startRound(game.round+1);
    return;
  }
  const alive=zombies.filter(z=>!z.dead).length;
  const cap=Math.min(10+game.round,26);
  if(game.toSpawn>0){
    game.spawnT-=dt;
    if(game.spawnT<=0&&alive<cap){
      let type=pickType(game.round);
      if(game.phase==='boss')type=Math.random()<0.6?'walker':'runner';
      if(game.event==='FRENZY'&&Math.random()<0.5)type='runner';
      if(game.event==='GAS DRAG'&&Math.random()<0.3)type='exploder';
      if(game.event==='NIGHTMARE'&&Math.random()<0.3)type='armored';
      spawnZombie(type);game.toSpawn--;
      game.spawnT=Math.max(0.4,2.1-game.round*0.07);
    }
  }
  if(game.round%10===0&&game.phase==='active'&&!nemesis&&!game.bossDone){
    game.bossDone=true;spawnBoss();
  }
  if(game.phase==='boss'&&nemesis&&nemesis.dead){
    nemesis=null;game.phase='active';$('botC').style.display='none';musicLevel(game.musicL);
  }
  if(game.bossDone&&!nemesis&&game.toSpawn<=0&&zombies.every(z=>z.dead)){
    game.bossDone=false;
    game.phase='intermission';game.phaseT=6;player.hp=Math.min(player.max,player.hp+player.max*0.35);
    player.lastUsed=false;showBanner('ROUND '+game.round+' CLEARED','BOSS SLAIN — +2500 PTS');givePoints(1000);
    sfx('buy');updateHUD();
  }
  if(game.phase==='active'&&game.toSpawn<=0&&zombies.every(z=>z.dead)){
    game.phase='intermission';game.phaseT=6.5;
    player.hp=Math.min(player.max,player.hp+pa40());player.lastUsed=false;
    showBanner('ROUND '+game.round+' CLEARED','NEXT WAVE...');
    updateHUD();sfx('buy');
  }
}
function pa40(){return player.max*0.35;}
