  if(force||hudCache.ar!==ar){hudCache.ar=ar;$('arBar').style.width=ar+'%';$('arWrap').style.display=ar>0?'block':'none';}
  const alive=zombies.filter(z=>!z.dead).length;
  const zt=game.phase==='intermission'?'PREPARE...':(alive+game.toSpawn)+' LEFT';
  if(force||hudCache.zt!==zt){hudCache.zt=zt;$(0,0)&&0;$('zleft').textContent=zt;}
  const pk=player.perks.map(id=>PERKS[id].n.split(' ')[1]).join(' · ');
  if(force||hudCache.pk!==pk){hudCache.pk=pk;$('perkIcons').innerHTML=player.perks.map(id=>'<span style="color:'+PERKS[id].c+'">'+PERKS[id].n+'</span>').join(' ');}
  if(nemesis&&!nemesis.dead){$('bossBar').style.width=clamp(nemesis.hp/nemesis.mhp*100,0,100)+'%';}
  $('upgl').innerHTML=player.weapUp[s.w]?'<span style="color:#e8b23a;font-size:10px;letter-spacing:2px">WAR FORGE '+UPG_N[player.weapUp[s.w]]+'</span>':'<span style="color:#555;font-size:9px;letter-spacing:1px">UNFORGED</span>';
}
/* ---------------- FLOW ---------------- */
function startGame(mi){
  ac();musicStart();
  game.state='play';game.points=500;game.round=0;game.kills=0;game.heads=0;game.shots=0;game.hits=0;game.earned=0;
  game.phase='idle';game.phaseT=1.6;game.toSpawn=0;game.bossDone=false;game.event=null;
  zombies=[];parts=[];nades=[];pickups=[];nemesis=null;
  loadMap(mi||settings.mapId);
  player.x=game.map.start.x;player.y=game.map.start.y;player.a=game.map.start.a||0;player.pitch=0;pitchAcc=0;
  player.hp=player.max=100;player.armor=0;player.perks=[];player.slots=[{w:'m1911',mag:7,res:84},null];player.cur=0;
  player.reloading=false;player.nades=2;player.weapUp={};player.ads=0;player.lastUsed=false;player.slideCd=0;player.slideT=0;
  boxRoll.on=false;boxRoll.done=false;boxRoll.result=null;
  $('menu').classList.remove('show');$('overM').classList.remove('show');$('pauseM').classList.remove('show');
  showBanner(game.map.name,'ROUND 1 INCOMING');updateHUD(true);
  if(!touchMode&&!locked){gameCanvas.requestPointerLock&&gameCanvas.requestPointerLock();}
}
function pauseGame(){if(game.state!=='play')return;game.state='pause';$('pauseM').classList.add('show');document.exitPointerLock&&document.exitPointerLock();refreshUI();}
function resumeGame(){game.state='play';$('pauseM').classList.remove('show');if(!touchMode)gameCanvas.requestPointerLock&&gameCanvas.requestPointerLock();}
function gameOver(){
  game.state='over';if(document.exitPointerLock)document.exitPointerLock();
  const P=loadProfile();P.rounds[game.mapIdx]=Math.max(P.rounds[game.mapIdx]||0,game.round);
  P.kills+=game.kills;P.heads+=game.heads;P.games++;SAVE('profile',P);
  $('overS').textContent='SURVIVED TO ROUND '+game.round+' — '+game.kills+' KILLS ('+game.heads+' HEADSHOTS) — '+game.earned+' POINTS EARNED — '+game.map.name;
  $('overM').classList.add('show');sfx('round');musicLevel(0);rumble(700,0.3,1);
}
function loadProfile(){return LOAD('profile',{rounds:[0,0,0,0],kills:0,heads:0,games:0});}
function showBanner(h,s){$('banH').textContent=h;$('banS').textContent=s||'';const b=$('ban');b.style.opacity=1;clearTimeout(b._t);b._t=setTimeout(()=>b.style.opacity=0,2800);}

/* ---------------- MAP LOAD ---------------- */
function loadMap(mi){
  settings.mapId=mi;SAVE('mapId',mi);
  const M=MAPS[mi];
  buildMap(mi);
  game.map=M;game.mapIdx=mi;
  M.tex=[makeWallTex(M.hues[0]),makeWallTex(M.hues[1]),makeWallTex(M.hues[2])];
  M.doorTex=makeMetalTex();
  M.perksA=M.perks.map(p=>({id:p[0],x:p[1],y:p[2]}));
  M.doorsA=M.doors.map(d=>{d.open=false;return {...d,px:d.cells[0][0]+0.5,py:d.cells[0][1]+0.5};});
  M.eggsA=M.eggs.map(e=>({x:e[0],y:e[1],dead:false}));
  M.radio={x:M.radio[0],y:M.radio[1]};
  M.hostile=0;
}
function makeMetalTex(){const c=mkCanvas(64,64),x=c.getContext('2d');
  x.fillStyle='#2a2d33';x.fillRect(0,0,64,64);
  for(let i=0;i<9;i++){x.fillStyle='#1c1f24';x.fillRect(i*7,0,3,64);}
  x.fillStyle='#8a2222';x.fillRect(0,28,64,4);x.fillStyle='#c94';x.font='bold 12px Arial';x.textAlign='center';x.fillText('LOCKED',32,20);
  for(let i=0;i<80;i++){x.fillStyle='rgba(0,0,0,.25)';x.fillRect((Math.random()*64)|0,(Math.random()*64)|0,2,2);}
  return c;}
/* ---------------- SPRITE RENDER ---------------- */
function drawSprite(img,tfX,tfY,wF,hF,zOff,alpha,glow){
  if(tfY<=0.12)return;
  const scale=RH/tfY * (wF*2.9);
  const sw=scale*(img.width/img.height)*(hF/wF);
  const sh=RH/tfY*hF;
  const scr=Math.floor(RW/2*(1+tfX/tfY));
  const startX=Math.floor(scr-sw/2),endX=Math.ceil(scr+sw/2);
  const floorY=horizon+RH/tfY*0.5;
  const top=floorY-sh-zOff*(RH/tfY);
  if(endX<0||startX>=RW)return;
  if(glow){ctx.save();ctx.shadowColor=glow;ctx.shadowBlur=sw*0.25;}
  for(let x=Math.max(0,startX);x<Math.min(RW,endX);x++){
    if(zbuf[x]<=tfY)continue;
    const u=(x-(scr-sw/2))/sw;
    const sxi=clamp(Math.floor(u*img.width),0,img.width-1);
    try{ctx.globalAlpha=alpha!=null?clamp(alpha,0,1):1;ctx.drawImage(img,sxi,0,1,img.height,x,top,1,sh);}catch(e){}
  }
  ctx.globalAlpha=1;if(glow)ctx.restore();
}
let horizon=135,texWall=null,darkFlick=0;
function render(){
  const p=player,M=game.map;
  const planeScale=Math.tan(settings.fov*Math.PI/360)*(1-0.35*p.ads);
  const dirX=Math.cos(p.a),dirY=Math.sin(p.a);
  const plX=-dirY*planeScale,plY=dirX*planeScale;
  horizon=RH/2+p.pitch*0.95+Math.sin(p.bob)*3-(p.crouch?9:0);
  // sky / ceiling
  const g1=ctx.createLinearGradient(0,0,0,Math.max(1,horizon|0));
  g1.addColorStop(0,M.sky[0]);g1.addColorStop(1,M.sky[1]);
  ctx.fillStyle=g1;ctx.fillRect(0,0,RW,Math.max(1,(horizon|0)+1));
  const g2=ctx.createLinearGradient(0,Math.max(0,horizon|0),0,RH);
  g2.addColorStop(0,M.flr[0]);g2.addColorStop(1,M.flr[1]);
  ctx.fillStyle=g2;ctx.fillRect(0,Math.max(0,horizon|0),RW,RH);
  // walls
  for(let x=0;x<RW;x++){
    const cam=2*x/RW-1;
    const rdx=dirX+plX*cam,rdy=dirY+plY*cam;
    const h=cast(p.x,p.y,rdx,rdy);
    const d=Math.max(0.06,h.d);
    zbuf[x]=d;
    const wh=RH/d,y0=horizon-wh/2;
    const mat=M.solid[h.my*MW+h.mx];
    const tex=mat>=2?(mat===2+M.doors.findIndex(dd=>!dd.open||dd.open)&&0)||texDoorFor(M,mat):(mat===0?M.tex[1]:M.tex[(h.mx*7+h.my*13)%3]);
    const wallX=h.side===0?(p.y+d*rdy):(p.x+d*rdx);
    let tx=Math.floor((wallX-Math.floor(wallX))*64);
    if((h.side===0&&rdx>0)||(h.side===1&&rdy<0))tx=63-tx;
    try{ctx.drawImage(tex,clamp(tex,0,63)>=0?clamp(tx,0,63):0,0,1,64,x,y0,1,wh);}catch(e){}
    const sh=clamp(d/(envDist()),0,0.86)+ (h.side===1?0.07:0);
    ctx.fillStyle='rgba('+M.tint+','+sh.toFixed(2)+')';
    ctx.fillRect(x,y0,1,wh+1);
  }
  // sprites
  const invDet=1/(plX*dirY-dirX*plY);
  const list=[];
  const push=(x,y,kind,o)=>{const rx=x-p.x,ry=y-p.y;const tfX=invDet*(dirY*rx-dirX*ry),tfY=invDet*(-plY*rx+plX*ry);
    if(tfY>0.15)list.push({tfX,tfY,d:tfY,kind,o});};
  for(const cr of M.props)push(cr[0],cr[1],'prop',{img:propImg(cr[2])});
  push(M.box.x,M.box.y,'box',null);
  push(M.forge.x,M.forge.y,'forge',null);
  for(const b of M.buys)push(b.x,b.y,'buy',b);
  for(const pk of M.perksA)push(pk.x,pk.y,'perk',pk);
  for(const d of M.doorsA)push(d.px,d.py,'doorL',d);
  for(const w of M.winW)push(w.wx-w.dx*0.02,w.wy-w.dy*0.02,'window',w);
  for(const g of M.eggsA)if(!g.dead)push(g.x,g.y,'egg',g);
  push(M.radio.x,M.radio.y,'radio',M.radio);
  for(const pk of pickups)push(pk.x,pk.y,'pickup',pk);
  for(const n of nades)push(n.x,n.y,'nade',n);
  for(const z of zombies){
    if(z.dead&&z.dt>0.95)continue;
    // spawn offset pos
    push(z.x,z.y,'zombie',z);
  }
  list.sort((a,b)=>b.d-a.d);
  for(const s of list)drawEntity(s);
  // particles
  for(const pt of parts){
    const rx=pt.x-p.x,ry=pt.y-p.y;
    const tfX=invDet*(dirY*rx-dirX*ry),tfY=invDet*(-plY*rx+plX*ry);
    if(tfY<=0.15)continue;
    const scr=Math.floor(RW/2*(1+tfX/tfY));
    if(scr<0||scr>=RW||zbuf[scr]<=tfY)continue;
    const size=Math.max(1,pt.s*RH/tfY*0.028);
    const yy=horizon+(0.5-pt.z)*(RH/tfY)+Math.abs(Math.sin(pt.life*13))*size;
    ctx.globalAlpha=clamp(pt.life*3,0,1);ctx.fillStyle=pt.c;
    ctx.fillRect(scr-size/2,yy-size/2,size,size);ctx.globalAlpha=1;
  }
  // environment fx / fog & flicker
  postFX();
  drawViewmodel();
}
function texDoorFor(M,mat){const di=mat-2;return (M.doors[di]&&M.doors[di].open)?M.tex[1]:M.doorTex;}
function envDist(){return 13+settings.fov*0.02;}
function drawEntity(s){
  const M=game.map,tNow=performance.now()/1000;
  if(s.kind==='prop')drawSpriteHL(s.o.imgM?propImg(s.o.imgM):propImgFromCache(s.o),s,{w:0.55,h:0.42,zOff:0,a:1});
  else if(s.kind==='prop'){const img=propImg(s.o[2]);drawSpriteHL(img,s,{w:0.5,h:0.3,zOff:0,a:1});}
  else if(s.kind==='box'){const img=(boxRoll.on||boxRoll.result)?chestOpenC:chestClosedC;
    drawSpriteHL(img,s,{w:0.72,h:0.55,zOff:0,a:1,glow:(boxRoll.on||boxRoll.result)?'#ffcc55':null});
    if(boxRoll.result){push2Label(WEAPONS[boxRoll.result].n.toUpperCase().split(' ')[0],'HOLD '+keyUse()+' TO TAKE','#7ef0ff',s,1.06,{a:1});}
    else if(!boxRoll.on)push2Label('MYSTERY BOX','✥950','#d8b04a',s,0.75,{a:0.9});}
  else if(s.kind==='forge')drawSpriteHL(forgeImg,s,{w:0.62,h:0.58,zOff:0,a:1,glow:'#e8742a'});
  else if(s.kind==='perk')drawSpriteHL(machineImg(PERKS[s.o.id].c,PERKS[s.o.id].n.split(' ')[0]),s,{w:0.6,h:0.92,zOff:0,a:1,glow:PERKS[s.o.id].c});
  else if(s.kind==='buy')drawSpriteHL(labelCR[s.o.w],s,{w:0.78,h:0.42,zOff:0.32,a:1,glow:'#ffb03a'});
  else if(s.kind==='doorL')if(!s.o.open)drawSpriteHL(doorLabel,s,{w:0.9,h:0.34,zOff:0.62,a:0.95});
  else if(s.kind==='window'){const img=windowCache[s.o.boards]!=null?windowCache[s.o.boards]:windowCache[0];drawSpriteHL(img,s,{w:0.86,h:1.1,zOff:0.04,a:1});}
  else if(s.kind==='egg')drawSpriteHL(gargoyleImg,s,{w:0.28,h:0.34,zOff:1.1+Math.sin(tNow*2)*0.05,a:0.95,glow:'#8cf'})
  else if(s.kind==='radio')drawSpriteHL(radioImg,s,{w:0.42,h:0.34,zOff:0.35,a:1});
  else if(s.kind==='pickup')drawSpriteHL(pickupImg(vs(s)),s,{w:0.4,h:0.26,zOff:0.06+Math.sin(tNow*3)*0.05,a:0.95});
  else if(s.kind==='nade')drawSpriteHL(nadeImg(vs(s)),s,{w:0.14,h:0.14,zOff:s.o.z,a:1});
  else if(s.kind==='zombie'){const z=s.o;drawZombieS(z,s,tNow);}
}
function drawSpriteHL(img,s,cfg){cfg.w2=cfg.w;drawS(img,s,cfg);}
function drawS(img,s,cfg){
  const scale=RH/s.tfY;
  const sw=cfg.w*scale,sh=cfg.h*scale;
  const scr=Math.floor(RW/2*(1+s.tfX/s.tfY));
  const startX=Math.floor(scr-sw/2),endX=Math.ceil(scr+sw/2);
  const floorY=horizon+scale*0.5;
  const top=floorY-sh-(cfg.zOff||0)*scale;
  if(endX<0||startX>=RW)return;
  if(cfg.glow){try{ctx.shadowColor=cfg.glow;ctx.shadowBlur=sw*0.22;}catch(e){}}
  const al=cfg.a!=null?cfg.a:1;
  for(let x=Math.max(0,startX);x<Math.min(RW,endX);x++){
    if(zbuf[x]<=s.tfY)continue;
    const u=(x-(scr-sw/2))/sw;
    const sxi=clamp(Math.floor(u*img.width),0,img.width-1);
    ctx.globalAlpha=clamp(al,0,1);
    try{ctx.drawImage(img,sxi,0,1,img.height,x,top,1,sh);}catch(e){}
  }
  try{ctx.shadowBlur=0;}catch(e){}
  ctx.globalAlpha=1;
}
function push2Label(t1,t2,col,s,zOff,cfg){const hl=labCache[t1+t2]||mkLabel(t1,t2,col);labCache[t1+t2]=hl;
  const sc=RH/s.tfY,sw=0.85*sc,sh=sw*64/256;
  const scr=Math.floor(RW/2*(1+s.tfX/s.tfY));
  const top=horizon+sc*0.5-(zOff)*sc-sh;
  for(let x=Math.max(0,Math.floor(scr-sw/2));x<Math.min(RW,Math.ceil(scr+sw/2));x++){
    if(zbuf[x]<=s.tfY)continue;
    const u=(x-(scr-sw/2))/sw,sxi=clamp(Math.floor(u*256),0,255);
    ctx.globalAlpha=cfg&&cfg.a!=null?cfg.a:1;
    try{ctx.drawImage(hl,sxi,0,1,64,x,top,1,sh);}catch(e){}
  }
  ctx.globalAlpha=1;}
function vs(o){return o;}
function drawZombieS(z,s,tNow){
  const art=ZART[z.t]||ZART.walker;
  let img,alpha=1,zOff=0,glow=null;
  if(z.dead){img=art.hurt[0];alpha=1-z.dt/0.9;zOff=z.dt*0.5;}
  else if(z.boss){img=art.frames[(z.t*4|0)%3];glow=z.tele>0?'#e34':'#a00';if(z.hurt>0)img=art.hurt[(z.t*9|0)%4];}
  else if(z.st==='break'){img=art.frames[3+(z.t*7|0)%2];}
  else if(z.st==='attack'){img=art.frames[3+(z.t*6|0)%2];glow='#b22';}
  else{const f=(z.t*z.sp*2.6|0)%3;img=art.frames[f];}
  if(!z.dead&&z.hurt>0)img=art.hurt[(z.t*10|0)%5>=art.hurt.length?0:(z.t*10|0)%5];
  if(z.t==='stalker'&&!z.dead&&z.st!=='attack'){const d=Math.hypot(z.x-player.x,z.y-player.y);alpha=clamp(0.2+1.2*(1-d/8),0.18,0.92);}
  if(z.t==='exploder'&&!z.dead){glow='#e8a23a';}
  drawS(img,s,{w:ZT[z.t].sz,h:ZT[z.t].zh*(z.t==='boss'?1.0:0.9),zOff,a:alpha,glow});
}

