/* ---------------- ART CACHE ---------------- */
const chestClosedC=makeChest(false),chestOpenC=makeChest(true);
const forgeImg=mkForge(),gargoyleImg=mkGargoyle(),radioImg=mkRadio();
const WINDOW_ART=(()=>{const a=[];for(let i=0;i<=4;i++)a.push(mkWindowFrame(i));return a;})();
let windowCache=WINDOW_ART;
const propCache={};
function propImg(kind){if(!propCache[kind])propCache[kind]=mkProp(kind);return propCache[kind];}
const machineCache={};
function machineImg(col,t){const key=col+t;if(!machineCache[key])machineCache[key]=mkMachine(col,t);return machineCache[key];}
const puCache={};
function pickupImg(k){if(!puCache[k])puCache[k]=mkPickup(k==='gun'?5:0);return puCache[k];}
const nadeArt=(()=>{const c=mkCanvas(10,10),x=c.getContext('2d');x.fillStyle='#37432c';x.beginPath();x.arc(5,5,4,0,TAU);x.fill();x.fillStyle='#777';x.fillRect(4,1,2,3);return c;})();
function nadeImg(){return nadeArt;}
const labCache={};
let labelCR={},doorLabel=null;
function eggRadius(){return 0.3;}
window.addEventListener('load',()=>{doorLabel=mkLabel('LOCKED DOOR','HOLD '+keyUse()+' TO BUY','#e05555',true);
  for(const w in WEAPONS){} // built per map below
});
/* ---------------- VIEWMODEL ---------------- */
function drawViewmodel(){
  const s=curW();if(!s)return;
  const w=WEAPONS[s.w],up=player.weapUp[s.w]||0;
  const kick=player.kick;
  const bobY=Math.sin(player.bob)*4*(1-player.ads*0.8),bobX=Math.cos(player.bob*0.5)*2;
  const sc=(RH/270)*(1+kick*0.05)*(0.62+0.38*(1-player.ads));
  ctx.save();
  ctx.translate(RW*0.7-350*(0,0)+RW*0.2*player.ads-  RW*0.06*0+RW*0*(s.w?1:0),RH*1.03-28*player.ads+bobY+kick*9);
  ctx.translate(RW*0.62,RH+10);
  ctx.scale(sc,sc);ctx.rotate(kick*0.05+bobX*0.001);
  const dark='#121416',mid='#2b2e33',metal='#4a4e55',wood='#4a2f18',acc='#c8a24a',gold=up>0;
  if(gold){ctx.fillStyle='rgba(200,162,74,0.16)';ctx.fillRect(-40,-80,80,80);}
  ctx.fillStyle='rgba(0,0,0,0.35)';ctx.fillRect(-26,-58,52,58);
  const c=w.c;
  if(c==='pistol'){
    ctx.fillStyle=mid;ctx.fillRect(-8,-34,16,20);ctx.fillStyle=metal;ctx.fillRect(-6,-46,12,14);
    ctx.fillStyle=dark;ctx.fillRect(-10,-16,20,16);ctx.fillStyle=up?'#c8a24a':'#333';ctx.fillRect(-2,-50,4,6);
  }else if(c==='revolver'){
    ctx.fillStyle=metal;ctx.fillRect(-5,-44,10,18);ctx.fillStyle=dark;ctx.fillRect(-9,-30,18,14);
    ctx.fillStyle=metal;ctx.fillRect(-9,-27,18,5);ctx.fillStyle='#222';ctx.fillRect(-9,-24,4,8);
  }else if(c==='smg'){
    ctx.fillStyle=mid;ctx.fillRect(-9,-30,18,24);ctx.fillStyle=metal;ctx.fillRect(-5,-52,10,26);
    ctx.fillStyle=dark;ctx.fillRect(-14,-10,10,16);ctx.fillRect(4,-10,10,16);ctx.fillStyle=dark;ctx.fillRect(-8,-38,16,10);
  }else if(c==='rifle'){
    ctx.fillStyle=mid;ctx.fillRect(-9,-30,18,22);ctx.fillStyle=metal;ctx.fillRect(-4,-54,8,26);
    ctx.fillStyle=wood;ctx.fillRect(-8,-16,16,14);ctx.fillStyle=dark;ctx.fillRect(-13,-40,26,5);
    ctx.fillStyle=up?'#e8b23a':'#222';ctx.fillRect(-4,-56,8,3);
  }else if(c==='pump'){
    ctx.fillStyle=wood;ctx.fillRect(-9,-24,18,18);ctx.fillStyle=metal;ctx.fillRect(-10,-58,8,36);ctx.fillRect(2,-58,8,36);
    ctx.fillStyle=dark;ctx.fillRect(-12,-14,24,12);ctx.fillStyle=up?'#c8a24a':'#555';ctx.fillRect(-14,-40,28,4);
  }else if(c==='bolt'){
    ctx.fillStyle=dark;ctx.fillRect(-24,-20,48,8);ctx.fillStyle=metal;ctx.fillRect(-4,-58,8,40);
    ctx.fillStyle=mid;ctx.fillRect(-8,-22,26,10);ctx.fillStyle='#222';ctx.fillRect(-14,-16,6,6);
    ctx.fillStyle=up?'#e8b23a':'#666';ctx.fillRect(0,-58,8,4);
  }else if(c==='lmg'){
    ctx.fillStyle=dark;ctx.fillRect(-14,-34,28,16);ctx.fillStyle=metal;ctx.fillRect(-4,-58,8,26);
    ctx.fillStyle='#222';ctx.fillRect(-6,-20,12,14);ctx.fillStyle=mid;ctx.fillRect(-16,-40,32,6);
    ctx.fillStyle=up?'#c8a24a':'#444';ctx.fillRect(-14,-38,28,2);
  }else if(c==='ray'){
    ctx.fillStyle='#1d3336';ctx.fillRect(-10,-30,20,22);ctx.fillStyle='#2e5f63';ctx.fillRect(-6,-50,12,22);
    ctx.fillStyle=acc;ctx.fillRect(-14,-32,28,4);ctx.strokeStyle='#7ef0ff';ctx.lineWidth=2;ctx.strokeRect(-7,-49,14,20);
    ctx.fillStyle='rgba(126,240,255,'+(0.4+kick*0.6)+')';ctx.fillRect(-4,-46,8,4);
  }else if(c==='gl'){
    ctx.fillStyle=dark;ctx.fillRect(-10,-40,20,14);ctx.fillStyle=metal;ctx.fillRect(-8,-58,16,20);
    ctx.fillStyle='#333';ctx.fillRect(-14,-26,28,10);ctx.fillStyle=up?'#e8b23a':'#555';ctx.fillRect(-3,-30,6,6);
  }
  if(kick>0.5){
    ctx.fillStyle='rgba(255,220,120,'+(kick-0.25)+')';
    ctx.beginPath();ctx.arc(0,-64,9*kick,0,TAU);ctx.fill();
  }
  ctx.restore();
}
/* ---------------- POST FX ---------------- */
let weatherBits=[];
function initWeather(){
  weatherBits=[];
  const w=game.map.weather;
  if(w==='rain'||w==='snow'){for(let i=0;i<70;i++)weatherBits.push({x:Math.random(),y:Math.random(),s:rnd(0.4,1)});}
}
function postFX(){
  const M=game.map,nw=performance.now()/1000;
  const rg=ctx.createRadialGradient(RW/2,RH*0.6,RH*0.28,RW/2,RH*0.55,RH*0.95);
  rg.addColorStop(0,'rgba(0,0,0,0)');
  rg.addColorStop(1,'rgba('+M.tint+','+(0.72+M.amb*0.001+darkFlick).toFixed(2)+')');
  ctx.fillStyle=rg;ctx.fillRect(0,0,RW,RH);
  if(M.weather==='red'){
    const f=Math.random()<M.flick?0.55:0;
    darkFlick=f*0.5;
    if(f){ctx.fillStyle='rgba(120,20,20,0.14)';ctx.fillRect(0,0,RW,RH);}
  } else if(M.weather==='fog'){
    ctx.fillStyle='rgba(120,125,135,0.13)';ctx.fillRect(0,0,RW,RH);
  }
  if(M.weather==='rain'){
    ctx.strokeStyle='rgba(170,190,220,0.3)';ctx.beginPath();
    for(const b of weatherBits){b.y+=0.022*b.s;if(b.y>1){b.y-=1;b.x=Math.random();}
      const x=b.x*RW,y=b.y*RH;ctx.moveTo(x,y);ctx.lineTo(x-2,y+7*b.s);}
    ctx.stroke();
  } else if(M.weather==='snow'){
    ctx.fillStyle='rgba(220,230,240,0.5)';
    for(const b of weatherBits){b.y+=0.004*b.s;b.x+=Math.sin(nw*2+b.s*9)*0.0016;if(b.y>1){b.y-=1;b.x=Math.random();}
      ctx.fillRect(b.x*RW,b.y*RH,b.s*2.2,b.s*2.2);}
  }
  // low hp red pulse
  const hpF=player.hp/player.max;
  if(hpF<0.45&&game.state==='play'){
    ctx.fillStyle='rgba(120,0,0,'+(0.3*(0.45-hpF)/0.45*(0.6+0.4*Math.sin(nw*8)))+')';
    ctx.fillRect(0,0,RW,RH);
  }
}
/* ---------------- MINIMAP ---------------- */
const mmC=$('minimap'),mm=mmC.getContext('2d');let mmZoom=1;
function drawMinimap(){
  const M=game.map,s=112/(MW*mmZoom)*(MW/MW),cell=112/(MW*mmZoom);
  mm.clearRect(0,0,112,112);mm.fillStyle='rgba(4,6,5,0.8)';mm.fillRect(0,0,112,112);
  const cx=mmZoom===1?0:clamp(player.x-MW/(2*mmZoom),0,MW-112/cell),cy=mmZoom===1?0:clamp(player.y-MH/(2*mmZoom),0,MH-112/cell);
  for(let y=MIN_Y; y<47;y++){
    const yy=Math.min(MH-1,Math.floor(cy+y/MMZStep()));
    break;
  }
  // simple full map render
  const px=Math.floor(player.x),py=Math.floor(player.y);
  for(let y=0;y<MH;y++)for(let x=0;x<MW;x++){
    const g=M.solid[y*MW+x];if(!g&&0)continue;
    if(g===0)continue;
    mm.fillStyle=g>=2?'#8a2222':(g===1?'#3a4438':'#444');
    mm.fillRect(x*cell,y*cell,cell,Math.max(1,cell));
  }
  // windows
  mm.fillStyle='#d8892a';
  for(const w of M.winW)mm.fillRect((w.x-0.5)*cell,(w.y-0.5)*cell,cell,Math.max(1,cell));
  // markers
  mm.fillStyle='#5ad';
  for(const b of M.buys)dot(b.x,b.y,'#5ad');
  for(const p of M.perksA)dot(p.x,p.y,'#7c7');
  dot(M.box.x,M.box.y,'#ffcc55');dot(M.forge.x,M.forge.y,'#e8742a');
  for(const p of pickups)dot(p.x,p.y,'#ff8');
  for(const n of nades)dot(n.x,n.y,'#fa4');
  for(const z of zombies){if(z.dead)continue;if(z.boss){mm.fillStyle='#e33';mm.fillRect((z.x-1.2)*cell,(z.y-1.2)*cell,cell*2.4,cell*2.4);}else dot(z.x,z.y,'#d33');}
  // player arrow
  mm.save();mm.translate(player.x*cell,player.y*cell);mm.rotate(player.a);
  mm.fillStyle='#fff';mm.beginPath();mm.moveTo(5,0);mm.lineTo(-3,-3);mm.lineTo(-3,3);mm.closePath();mm.fill();mm.restore();
  function dot(x,y,c){mm.fillStyle=c;mm.fillRect(x*cell-1.5,y*cell-1.5,3,3);}
}
function MMZStep(){return 1;}
const MIN_X=0,MIN_Y=0;

