/* ---------------- UPDATE ---------------- */
let radioCd=0;
function updateWorld(dt){
  updateWindows(dt);
  updatePlayer(dt);
  flowT-=dt;if(flowT<=0){computeFlow();flowT=0.3;}
  for(const z of zombies)updateZombie(z,dt);
  zombies=zombies.filter(z=>!(z.dead&&z.dt>0.9));
  for(let i=parts.length-1;i>=0;i--){const p=parts[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)parts.splice(i,1);}
  updateNades(dt);
  updateBox(dt);
  roundLogic(dt);
  radioCd=Math.max(0,radioCd-dt);if(radioAct&&radioAct._cd!==undefined&&radioAct._cd>0){radioAct._cd=Math.max(0,radioAct._cd-dt);}
  game.shake=Math.max(0,game.shake-dt*2.2);
  const alive=zombies.filter(z=>!z.dead).length;
  musicLevel(clamp(game.musicL*(0.6+0.4*Math.min(1,alive/10)),0.15,1));
  if(Math.random()<dt*0.8)sfx('groan',{pan:rnd(-1,1),v:0.5});
  damageVigTick(dt);
  updateHUD();
}
function damageVigTick(dt){
  const k=clamp(1-player.hp/(player.max*0.55),0,1);
  dmgVig(k*0.35+(game.shake>0.8?0.12:0));
}
/* ---------------- INPUT WIRING ---------------- */
gameCanvas.addEventListener('mousedown',e=>{
  if(game.state!=='play')return;
  if(!locked&&!touchMode)gameCanvas.requestPointerLock&&gameCanvas.requestPointerLock();
  if(e.button===0)mouseFire=true;if(e.button===2)mouseAim=true;
});
addEventListener('mouseup',e=>{if(e.button===0)mouseFire=false;if(e.button===2)mouseAim=false;});
addEventListener('contextmenu',e=>{if(e.target===gameCanvas)e.preventDefault();});
document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===gameCanvas;});
addEventListener('mousemove',e=>{
  if(!locked||game.state!=='play')return;
  const sMul=(0.55+0.45*(1-player.ads*0.4));
  lookAcc+=e.movementX*0.0021*settings.sens*sMul;
  pitchAcc+=e.movementY*0.8*settings.sens*(settings.invert?1:-1);
});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.state==='play')pauseGame();});
/* touch */
if(('ontouchstart' in window)||navigator.maxTouchPoints>0){touchMode=true;document.body.classList.add('touch');}
let stkId=null,lookId=null,stkBase={x:0,y:0},lookLast={x:0,y:0};
function bindHold(id,on,off){const el=$(id);
  el.addEventListener('pointerdown',e=>{e.preventDefault();try{el.setPointerCapture(e.pointerId);}catch(err){}on();});
  el.addEventListener('pointerup',()=>off());el.addEventListener('pointercancel',()=>off());}
bindHold('tFire',()=>touchFire=true,()=>touchFire=false);
bindHold('tAim',()=>{adsToggle=!adsToggle;$('tAim').style.borderColor=adsToggle?'#ffb03a':'rgba(255,255,255,.25)';},()=>{});
bindHold('tReload',()=>reloadT_=true,()=>{});
bindHold('tSwap',()=>swapT_=true,()=>{});
bindHold('tUse',()=>touchUse=true,()=>touchUse=false);
bindHold('tNade',()=>nadeT_=true,()=>{});
bindHold('tMelee',()=>meleeT_=true,()=>{});
bindHold('tCrouch',()=>{crouchTouch=!crouchTouch;$('tCrouch').style.borderColor=crouchTouch?'#ffb03a':'rgba(255,255,255,.25)';},()=>{});
let crouchTouch=false;
gameCanvas.addEventListener('pointerdown',e=>{
  if(!touchMode||game.state!=='play')return;
  if(e.clientX<innerWidth*0.42&&stkId===null){
    stkId=e.pointerId;stkBase={x:e.clientX,y:e.clientY};touchMoving={x:0,y:0};
    const s=$('stk');s.style.left=(e.clientX-60)+'px';s.style.top=(e.clientY-60)+'px';s.style.bottom='auto';
  }else if(lookId===null){lookId=e.pointerId;lookLast={x:e.clientX,y:e.clientY};}
});
gameCanvas.addEventListener('pointermove',e=>{
  if(!touchMode||game.state!=='play')return;
  if(e.pointerId===stkId){
    let dx=e.clientX-stkBase.x,dy=e.clientY-stkBase.y;const m=Math.hypot(dx,dy),R=60;
    if(m>R){dx=dx/m*R;dy=dy/m*R;}
    touchMoving.x=dx/R;touchMoving.y=dy/R;
    $('knob').style.transform='translate(calc(-50% + '+dx+'px),calc(-50% + '+dy+'px))';
  }else if(e.pointerId===lookId){
    lookAcc+=(e.clientX-lookLast.x)*0.0052*settings.sens*(0.55+0.45*(1-player.ads));
    pitchAcc+=(e.clientY-lookLast.y)*1.0*settings.sens*(settings.invert?1:-1);
    lookLast={x:e.clientX,y:e.clientY};
  }
});
function endT(e){
  if(e.pointerId===stkId){stkId=null;touchMoving={x:0,y:0};$('stk').style.left='5%';$('stk').style.top='auto';$('stk').style.bottom='10%';$('knob').style.transform='translate(-50%,-50%)';}
  if(e.pointerId===lookId)lookId=null;
}
gameCanvas.addEventListener('pointerup',endT);gameCanvas.addEventListener('pointercancel',endT);
setInterval(()=>{$('tUse').style.display=(game.state==='play'&&lastTarget&&lastTarget.k!=='egg'&&lastTarget.k!=='repair')?'flex':'none';
  touchADS=adsToggle;if(touchUse&&lastTarget&&lastTarget.k==='repair'&&false)touchUse=false;},120);
/* ---------------- MENUS ---------------- */
function refreshUI(){
  const P=loadProfile();
  $('pros').innerHTML='RANK: '+rankName(P.kills)+' · TOTAL KILLS: '+P.kills+' · BEST ROUNDS: '+
    MAPS.map((m,i)=>'<span title="'+m.name+'">'+(i+1)+': '+(P.rounds[i]||0)+'</span>').join(' · ');
  $('invY').textContent='Invert Y: '+(settings.invert?'ON':'OFF');$('invY2').textContent='Invert Y: '+(settings.invert?'ON':'OFF');
  $('sens').value=settings.sens;$('sens2').value=settings.sens;
  buildBtns('mapBtns','ZONE: ',MAPS.map(m=>m.name.split(' ')[0].replace('OPERATION','FROST').replace('THE ','')),settings.mapId,i=>{
    settings.mapId=i;SAVE('mapId',i);refreshUI();});
  buildBtns('padBtns','XBOX: ',Object.values(PRESETS).map(p=>p.name),settings.preset,id=>{
    settings.preset=id;preset=PRESETS[id];SAVE('preset',id);refreshUI();buildTable('ctrlT');});
  buildBtns('padBtns2','XBOX: ',Object.values(PRESETS).map((p,i)=>PRESETS[Object.keys(PRESETS)[i]].name),settings.preset,id=>{
    settings.preset=id;preset=PRESETS[id];SAVE('preset',id);refreshUI();});
  buildBtns('qBtns','QUALITY: ',['LOW','MED','HIGH','ULTRA'],settings.quality,id=>{
    settings.quality=id;SAVE('quality',id);setQuality();refreshUI();});
  buildTable('ctrlT');
  $('fovB').textContent='FOV: '+settings.fov+'°';
}
function buildBtns(id,label,items,sel,onPick){
  const box=$(id);box.innerHTML='';
  items.forEach((it,i)=>{const b=document.createElement('button');b.className='btn'+((it===sel||i===sel)?' sel':'');
    if(typeof items[i]==='string'&&typeof sel==='number')b.className='btn'+(i===sel?' sel':'');
    if(typeof sel==='string')b.className='btn'+(it===sel?' sel':'');
    b.textContent=(label&&!box.dataset.lab&&(b.dataset.lab=1))?items[0]:0;
    b.textContent=it;
    b.onclick=()=>onPick(typeof sel==='number'?i:it);
    box.appendChild(b);});
}
function buildTable(id){
  const m=preset.map,kb={fire:'LMB',aim:'RMB',reload:'R',swap:'Q/E',melee:'V',sprint:'SHIFT',interact:'HOLD F',pause:'ESC'};
  const map=m,pd={fire:map.fire,aim:map.aim,reload:map.reload,swap:map.swap+'/'+map.item,melee:map.melee,sprint:map.sprint,interact:'HOLD '+map.interact,pause:'MENU'};
  let h='<table><tr><td style="color:#d43c3c;letter-spacing:2px"><b>ACTION</b></td><td><b>XBOX PAD</b></td><td><b>KEYS</b></td></tr>';
  for(const k of['fire','aim','reload','swap','melee','sprint','interact','pause'])
    h+='<tr><td>'+k.toUpperCase()+'</td><td><b>'+pd[k]+'</b></td><td><b>'+kb[k]+'</b></td></tr>';
  h+='<tr><td>MOVE / LOOK</td><td><b>Sticks'+(preset.stickSwap?' (SWAPPED)':'')+'</b></td><td><b>WASD / Mouse</b></td></tr>';
  h+='<tr><td>FRAG GRENADE</td><td><b>'+(map.item==='LB'?'RB':'LB')+'</b></td><td><b>G</b></td></tr>';
  h+='<tr><td>CROUCH / SLIDE</td><td><b>DPAD-DOWN</b></td><td><b>C (sprint+C=slide)</b></td></tr></table>';
  $(id).innerHTML=h;
}
function rankName(k){return k>40000?'GENERAL':k>15000?'COLONEL':k>6000?'MAJOR':k>2000?'CAPTAIN':k>700?'SERGEANT':k>150?'CORPORAL':'RECRUIT';}
$('startB').onclick=()=>startGame(settings.mapId||0);
$('resumeB').onclick=resumeGame;$('restartB').onclick=()=>startGame(game.mapIdx||0);
$('quitB').onclick=()=>{game.state='menu';$('pauseM').classList.remove('show');$('menu').classList.add('show');refreshUI();document.exitPointerLock&&document.exitPointerLock();};
$('againB').onclick=()=>startGame(game.mapIdx||0);
$('menuB').onclick=()=>{game.state='menu';$('overM').classList.remove('show');$('menu').classList.add('show');refreshUI();};
$('muteB').onclick=()=>{muted=!muted;ac();$('muteB').textContent=muted?'🔇':'🔊';if(!muted)musicStart();};
$('pauseB').onclick=pauseGame;
$('invY').onclick=$('invY2').onclick=()=>{settings.invert=!settings.invert;SAVE('invert',settings.invert);refreshUI();};
$('sens').oninput=$('sens2').oninput=e=>{settings.sens=+e.target.value;SAVE('sens',settings.sens);$('sens').value=settings.sens;$('sens2').value=settings.sens;};
$('fovB').onclick=()=>{const opts=[70,80,90,100];settings.fov=opts[(opts.indexOf(settings.fov)+1)%4];SAVE('fov',settings.fov);refreshUI();};
/* gamepad menu navigation */
setInterval(()=>{
  if(!pollPad())return;
  if(game.state==='menu'&&(padBtn('A')||padBtn('MENU'))){startGame(settings.mapId||0);}
  else if(game.state==='over'&&(padBtn('A')||padBtn('B'))){startGame(game.mapIdx||0);}
  else if(game.state==='pause'){
    if(padBtn('A')||padBtn('B'))resumeGame();
    if(padBtn('X'))startGame(game.mapIdx||0);
    if(padBtn('LB')||padBtn('RB')){
      const ids=Object.keys(PRESETS);let i=ids.indexOf(settings.preset);
      if(!padMenuCool){i=(i+1)%ids.length;settings.preset=ids[i];preset=PRESETS[ids[i]];SAVE('preset',ids[i]);refreshUI();toast('PRESET: '+preset.name);padMenuCool=true;setTimeout(()=>padMenuCool=false,400);}
    }
  }
},90);
let padMenuCool=false;
/* ---------------- MAIN LOOP ---------------- */
let lastF=performance.now(),fpsA=60;
function loop(now){
  requestAnimationFrame(loop);
  let dt=(now-lastF)/1000;lastF=now;
  if(dt>0.05)dt=0.05;
  if(game.state==='play'){
    readInput(dt);
    updateWorld(dt);
    render();
    drawMinimap();
  } else if(game.state==='pause'){
    render();
  }
  fpsA=fpsA*0.95+((1/Math.max(0.001,dt)))*0.05;
}
function render(){
  const p=player,M=game.map;
  const tS=performance.now()/1000;
  const shx=Math.sin(tS*47)*game.shake*7,shy=Math.cos(tS*39)*game.shake*5;
  ctx.setTransform(1,0,0,1,shx,shy);
  const planeScale=Math.tan(settings.fov*Math.PI/360)*(1-0.35*p.ads);
  const dirX=Math.cos(p.a),dirY=Math.sin(p.a);
  const plX=-dirY*planeScale,plY=dirX*planeScale;
  horizon=RH/2+p.pitch*0.95+Math.sin(p.bob)*3-(p.crouch?9:0);
  const g1=ctx.createLinearGradient(0,0,0,Math.max(1,horizon|0));
  g1.addColorStop(0,M.sky[0]);g1.addColorStop(1,M.sky[1]);
  ctx.fillStyle=g1;ctx.fillRect(0,0,RW,Math.max(1,(horizon|0)+2));
  const g2=ctx.createLinearGradient(0,Math.max(0,horizon|0),0,RH);
  g2.addColorStop(0,M.flr[0]);g2.addColorStop(1,M.flr[1]);
  ctx.fillStyle=g2;ctx.fillRect(0,Math.max(0,horizon|0),RW,RH);
  for(let x=0;x<RW;x++){
    const cam=2*x/RW-1;
    const rdx=dirX+plX*cam,rdy=dirY+plY*cam;
    const h=cast(p.x,p.y,rdx,rdy);
    const d=Math.max(0.06,h.d);
    zbuf[x]=d;
    const wh=RH/d,y0=horizon-wh/2;
    const mat=M.solid[h.my*MW+h.mx];
    const tex=mat>=2?(M.doors[mat-2]&&M.doors[mat-2].open?M.tex[1]:M.doorTex):M.tex[(h.mx*7+h.my*13)%3];
    const wallX=h.side===0?(p.y+d*rdy):(p.x+d*rdx);
    let tx=Math.floor((wallX-Math.floor(wallX))*64);
    if((h.side===0&&rdx>0)||(h.side===1&&rdy<0))tx=63-tx;
    try{ctx.drawImage(tex,clamp(tx,0,63),0,1,64,x,y0,1,wh);}catch(e){}
    const sh=clamp(d/envDist(),0,0.86)+(h.side===1?0.07:0);
    ctx.fillStyle='rgba(0,0,0,'+sh.toFixed(2)+')';
    ctx.fillRect(x,y0,1,wh+1);
  }
  const invDet=1/(plX*dirY-dirX*plY);
  const list=[];
  const push=(x,y,kind,o)=>{const rx=x-p.x,ry=y-p.y;
    const tfX=invDet*(dirY*rx-dirX*ry),tfY=invDet*(-plY*rx+plX*ry);
    if(tfY>0.15)list.push({tfX,tfY,d:tfY,kind,o});};
  for(const cr of M.props)push(cr[0],cr[1],'prop',cr);
  push(M.box.x,M.box.y,'box',null);
  push(M.forge.x,M.forge.y,'forge',null);
  for(const b of M.buys)push(b.x,b.y,'buy',b);
  for(const pk of M.perksA)push(pk.x,pk.y,'perk',pk);
  for(const d of M.doorsA)push(d.px,d.py,'doorL',d);
  for(const w of M.winW)push(w.wx-w.dx*0.02,w.wy-w.dy*0.02,'window',w);
  for(const gg of M.eggsA)if(!gg.dead)push(gg.x,gg.y,'egg',gg);
  push(M.radio.x,M.radio.y,'radio',M.radio);
  for(const pk of pickups)push(pk.x,pk.y,'pickup',pk);
  for(const n of nades)push(n.x,n.y,'nade',n);
  for(const z of zombies){if(z.dead&&z.dt>0.95)continue;push(z.x,z.y,'zombie',z);}
  list.sort((a,b)=>b.d-a.d);
  for(const s of list)drawEntity(s);
  for(const pt of parts){
    const rx=pt.x-p.x,ry=pt.y-p.y;
    const tfX=invDet*(dirY*rx-dirX*ry),tfY=invDet*(-plY*rx+plX*ry);
    if(tfY<=0.15)continue;
    const scr=Math.floor(RW/2*(1+tfX/tfY));
    if(scr<0||scr>=RW||zbuf[scr]<=tfY)continue;
    const size=Math.max(1,pt.s*RH/tfY*0.028);
    const yy=horizon+(0.5-pt.z)*(RH/tfY)+Math.abs(Math.sin(pt.life*13))*size;
    ctx.globalAlpha=clamp(pt.life*3,0,1);ctx.fillStyle=pt.c;
    ctx.fillRect(scr-size/2,yy-size/2,size,size);ctx.globalAlpha=1;
  }
  postFX();
  drawViewmodel();
  ctx.setTransform(1,0,0,1,0,0);
}
/* boot */
loadMap(clamp(settings.mapId,0,MAPS.length-1));
refreshUI();
updateHUD&&updateHUD(true);
requestAnimationFrame(loop);

