function loop(now){
  requestAnimationFrame(loop);
  let dt=(now-lastF)/1000;lastF=now;
  if(dt>0.05)dt=0.05;
  if(game.state==='play'){readInput(dt);updateWorld(dt);render();drawMinimap();}
  else if(game.state==='pause')render();
}
