/* ---------------- WORLD RENDER ---------------- */
function render(){
  const p=player,M=game.map;
  const tS=performance.now()/1000;
  const shx=Math.sin(tS*47)*game.shake*7,shy=Math.cos(tS*39)*game.shake*5;
  ctx.setTransform(1,0,0,1,shx,shy);
  const planeScale=Math.tan(settings.fov*Math.PI/360)*(1-0.35*p.ads);
  const dirX=Math.cos(p.a),dirY=Math.sin(p.a);
  const plX=-dirY*planeScale,plY=dirX*planeScale;
  horizon=RH/2+p.pitch*0.95+Math.sin(p.bob)*3-(p.crouch?9:0);
  const g1=ctx.createLinearGradient(0,0,0,Math.max(1,horizon|0));
  g1.addColorStop(0,M.sky[0]);g1.addColorStop(1,M.sky[1]);
  ctx.fillStyle=g1;ctx.fillRect(0,0,RW,Math.max(1,(horizon|0)+2));
  const g2=ctx.createLinearGradient(0,Math.max(0,horizon|0),0,RH);
  g2.addColorStop(0,M.flr[0]);g2.addColorStop(1,M.flr[1]);
  ctx.fillStyle=g2;ctx.fillRect(0,Math.max(0,horizon|0),RW,RH);
  for(let x=0;x<RW;x++){
    const cam=2*x/RW-1;
    const rdx=dirX+plX*cam,rdy=dirY+plY*cam;
    const h=cast(p.x,p.y,rdx,rdy);
    const d=Math.max(0.06,h.d);
    zbuf[x]=d;
    const wh=RH/d,y0=horizon-wh/2;
    const mat=M.solid[h.my*MW+h.mx];
    const tex=mat>=2?((M.doors[mat-2]||{}).open?M.tex[1]:M.doorTex):M.tex[(h.mx*7+h.my*13)%3];
    const wallX=h.side===0?(p.y+d*rdy):(p.x+d*rdx);
    let tx=Math.floor((wallX-Math.floor(wallX))*64);
    if((h.side===0&&rdx>0)||(h.side===1&&rdy<0))tx=63-tx;
    try{ctx.drawImage(tex,clamp(tx,0,63),0,1,64,x,y0,1,wh);}catch(e){}
    const sh=clamp(d/envDist(),0,0.86)+(h.side===1?0.07:0);
    ctx.fillStyle='rgba(0,0,0,'+sh.toFixed(2)+')';
    ctx.fillRect(x,y0,1,wh+1);
  }
  const invDet=1/(plX*dirY-dirX*plY);
  const list=[];
  const push=(x,y,kind,o)=>{const rx=x-p.x,ry=y-p.y;
    const tfX=invDet*(dirY*rx-dirX*ry),tfY=invDet*(-plY*rx+plX*ry);
    if(tfY>0.15)list.push({tfX,tfY,d:tfY,kind,o});};
  for(const cr of M.props)push(cr[0],cr[1],'prop',cr);
  push(M.box.x,M.box.y,'box',null);
  push(M.forge.x,M.forge.y,'forge',null);
  for(const b of M.buys)push(b.x,b.y,'buy',b);
  for(const pk of M.perksA)push(pk.x,pk.y,'perk',pk);
  for(const d of M.doorsA)push(d.px,d.py,'doorL',d);
  for(const w of M.winW)push(w.wx-w.dx*0.02,w.wy-w.dy*0.02,'window',w);
  for(const gg of M.eggsA)if(!gg.dead)push(gg.x,gg.y,'egg',gg);
  push(M.radio.x,M.radio.y,'radio',M.radio);
  for(const pk of pickups)push(pk.x,pk.y,'pickup',pk);
  for(const n of nades)push(n.x,n.y,'nade',n);
  for(const z of zombies){if(z.dead&&z.dt>0.95)continue;push(z.x,z.y,'zombie',z);}
  list.sort((a,b)=>b.d-a.d);
  for(const s of list)drawEntity(s);
  for(const pt of parts){
    const rx=pt.x-p.x,ry=pt.y-p.y;
    const tfX=invDet*(dirY*rx-dirX*ry),tfY=invDet*(-plY*rx+plX*ry);
    if(tfY<=0.15)continue;
    const scr=Math.floor(RW/2*(1+tfX/tfY));
    if(scr<0||scr>=RW||zbuf[scr]<=tfY)continue;
    const size=Math.max(1,pt.s*RH/tfY*0.028);
    const yy=horizon+(0.5-pt.z)*(RH/tfY)+Math.abs(Math.sin(pt.life*13))*size;
    ctx.globalAlpha=clamp(pt.life*3,0,1);ctx.fillStyle=pt.c;
    ctx.fillRect(scr-size/2,yy-size/2,size,size);ctx.globalAlpha=1;
  }
  postFX();
  drawViewmodel();
  ctx.setTransform(1,0,0,1,0,0);
}
/* boot */
loadMap(clamp(settings.mapId||0,0,MAPS.length-1));
refreshUI();
updateHUD();
requestAnimationFrame(loop);
