// Map connectivity validator: extracts MW/MH/ringCarve/MAPS/buildMap from the game script
const fs=require('fs');
const src=fs.readFileSync('/tmp/opencode/cz_script.js','utf8');
const s0=src.indexOf('const MW=32'),s1=src.indexOf('const isWall=');
if(s0<0||s1<0){console.log('markers not found');process.exit(1);}
const seg=src.slice(s0,s1);
const sandbox={};
const fn=new Function('game',`
  let isWallRemoved=''; // strip isWall
  ${''}
`,'');
// We slice only up to isWall, so buildMap is included; but isWall references game.map -> it's after slice, fine.
const game={map:null};
const out=new Function('game',seg+'\nreturn {MW,MH,MAPS,buildMap};')(game);
const {MW,MH,MAPS,buildMap}=out;
let fails=0;
function chk(c,msg){if(!c){fails++;console.log('  FAIL: '+msg);}}
MAPS.forEach((M,mi)=>{
  console.log('MAP '+(mi)+' '+M.name);
  // rebuild solid without doors to check door cells were floor
  const solidNoDoor=buildMap(mi).solid && 0;
  // buildMap closes doors; recompute open base
  const a=[];(function(){for(let y=1;y<MH-1;y++)for(let x=1;x<MW-1;x++)if(Math.min(x,y,MW-1-x,MH-1-y)===1)a.push([x,y]);})();
  const rects={
    0:[[8,8,23,23],[15,1,16,9],[1,15,9,16],[23,15,30,16],[15,23,16,26],[2,4,7,9],[24,4,29,9],[12,2,19,6],[9,25,22,28],[25,25,28,28],[26,10,27,24],[9,10,22,10]],
    1:[[12,12,19,19],[15,1,16,30],[1,15,30,16],[2,2,9,9],[10,3,14,4],[22,2,29,9],[17,3,21,4],[2,22,9,29],[10,27,14,28],[22,22,29,29],[17,27,21,28],[6,10,9,14]],
    2:[[8,8,23,23],[15,1,16,23],[15,24,16,28],[2,12,7,19],[24,12,28,19],[13,2,18,7],[2,2,5,5],[27,2,29,4],[9,25,22,28],[2,26,6,28],[26,26,28,28],[3,8,4,11],[28,8,29,10],[6,16,7,16]],
    3:[[2,2,6,29],[15,2,16,29],[25,2,29,29],[2,2,29,5],[2,26,29,29],[7,15,14,16],[17,15,24,16],[10,8,13,13],[14,10,14,11],[18,20,23,23],[24,21,24,22]]}[mi];
  const base=new Uint8Array(MW*MH).fill(1);
  for(const [x0,y0,x1,y1] of a)base[y0*MW+x0]=0;
  for(const r of rects)for(let y=r[1];y<=r[3];y++)for(let x=r[0];x<=r[2];x++)if(x>0&&y>0&&x<MW-1&&y<MH-1)base[y*MW+x]=0;
  const dm=buildMap(mi);
  const S=dm.solid;
  // door cells were open before
  M.doors.forEach((d,di)=>d.cells.forEach(c=>chk(base[c[1]*MW+c[0]]===0,`door${di} cell ${c} not floor pre-door`)));
  // markers open
  const marks=[];
  M.buys.forEach(b=>marks.push([b.x,b.y,'buy '+b.w]));
  M.perks.forEach(p=>marks.push([p[1],p[2],'perk '+p[0]]));
  marks.push([M.forge.x,M.forge.y,'forge']);marks.push([M.box.x,M.box.y,'box']);
  marks.push([M.start.x,M.start.y,'start']);marks.push([M.radio[0],M.radio[1],'radio']);
  M.props.forEach(p=>marks.push([p[0],p[1],'prop']));
  M.eggs.forEach(e=>marks.push([e[0],e[1],'egg']));
  marks.forEach(([x,y,l])=>chk(S[Math.floor(y)*MW+Math.floor(x)]===0,`${l} at ${x},${y} is inside wall`));
  // windows: floor open, facing wall solid
  M.win.forEach(([fx,fy,dx,dy])=>{chk(S[fy*MW+fx]===0,`window floor ${fx},${fy} not open`);
    const wx=fx+dx,wy=fy+dy;const inb=(wx>=0&&wy>=0&&wx<MW&&wy<MH);
    chk(!inb||S[wy*MW+wx]>0,(S[wy*MW+wx]===0&&inb)?`window ${fx},${fy} dir ${dx},${dy} faces open corridor (fake spawn)`:`window facing ${wx},${wy} unspecified`);});
  // BFS from start over reachable open cells
  const sx=Math.floor(M.start.x),sy=Math.floor(M.start.y);
  const seen=new Uint8Array(MW*MH);const q=[[sx,sy]];seen[sy*MW+sx]=1;
  while(q.length){const [x,y]=q.pop();for(const [nx,ny] of [[x+1,y],[x-1,y],[x,y+1],[x,y-1]]){if(nx<0||ny<0||nx>=MW||ny>=MH)continue;const i=ny*MW+nx;if(!seen[i]&&S[i]===0){seen[i]=1;q.push([nx,ny]);}}}
  const reach=(x,y)=>{const c=[[Math.floor(x),Math.floor(y)]];for(const [cx,cy] of c)if(seen[cy*MW+cx])return true;
    // adjacency within 1.7 units (buy across a wall/door)
    for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){
      const nx=Math.floor(x)+dx,ny=Math.floor(y)+dy;
      if(nx<0||ny<0||nx>=MW||ny>=MH)continue;
      if(seen[ny*MW+nx]&&Math.hypot(nx+0.5-x,ny+0.5-y)<1.9)return true;}
    return false;};
  marks.forEach(([x,y,l])=>{if(['start','prop','buy','perk','forge','box','radio','egg'].some(k=>l.startsWith(k)))
    chk(reach(x,y)&&S[Math.floor(y)*MW+Math.floor(x)]===0?true:reach(x,y)||(l.startsWith('prop')),`${l} (${x},${y}) UNREACHABLE from start (gated?)`);});
  // doors reachable to buy
  M.doors.forEach((d,di)=>{let ok=reach(d.cells[0][0]+0.5,d.cells[0][1]+0.5);
    chk(ok,`door${di} (${d.name}) not buyable from reachable zone`);});
  // count reachable open area
  let open=0,seen2=0;for(let i=0;i<MW*MH;i++){if(S[i]===0)open++;if(seen[i])seen2++;}
  console.log('  open cells: '+open+' reachable: '+seen2+(seen2/open<0.6?'  (partial map reachable — gated areas exist)':''));
});
console.log(fails===0?'MAP CHECKS: ALL PASSED':('MAP CHECKS: '+fails+' FAILURES'));

