// Runtime smoke test: stub DOM/canvas/audio, eval the game script, simulate frames.
const fs=require('fs'),vm=require('vm');
const code=fs.readFileSync('/tmp/opencode/cz_script.js','utf8');

function mkCtx(){
  const grad=()=>({addColorStop(){}});
  return new Proxy({},{
    get(t,p){
      if(p==='createLinearGradient'||p==='createRadialGradient')return grad;
      if(t[p]!==undefined)return t[p];
      return ()=>{};
    },
    set(t,p,v){t[p]=v;return true;}
  });
}
const els={};
function getEl(id){
  if(els[id])return els[id];
  const e={
    id,style:{},textContent:'',innerHTML:'',width:300,height:150,
    classList:{add(){},remove(){},toggle(){},contains:()=>false},
    children:[],dataset:{},
    addEventListener(){},
    appendChild(c){this.children.push(c);},
    getContext:()=>mkCtx(),
    requestPointerLock(){},setPointerCapture(){},
    onclick:null,oninput:null,
  };
  els[id]=e;return e;
}
const L={};
const sandbox={
  console,setTimeout,clearTimeout,setInterval,performance,Math,Date,JSON,Object,Array,Uint8Array,Int16Array,Float32Array,Promise,Error,
  document:{
    getElementById:getEl,
    createElement:()=>{const c={width:0,height:0,getContext:()=>mkCtx(),style:{}};return c;},
    addEventListener(){},exitPointerLock(){},
    pointerLockElement:null,hidden:false,
    body:{classList:{add(){},remove(){}}},
  },
  window:null,navigator:{getGamepads:()=>[],maxTouchPoints:0,userAgent:'test'},
  localStorage:{_d:{},getItem(k){return this._d[k]||null;},setItem(k,v){this._d[k]=v;},removeItem(k){delete this._d[k];}},
  requestAnimationFrame(cb){sandbox.__raf=cb;return 1;},
  addEventListener(t,f){(L[t]=L[t]||[]).push(f);},
};
sandbox.window=sandbox;
sandbox.self=sandbox;
sandbox.innerWidth=1280;sandbox.innerHeight=720;
sandbox.AudioContext=class{
  constructor(){this.currentTime=0;this.state='running';this.destination={};this.sampleRate=44100;}
  resume(){}
  createGain(){return {gain:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){},linearRampToValueAtTime(){},setTargetAtTime(){}} ,connect(){},disconnect(){}};}
  createOscillator(){return {type:'',frequency:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){},linearRampToValueAtTime(){}},connect(){},start(){},stop(){}};}
  createBufferSource(){return {buffer:null,connect(){},start(){},stop(){}};}
  createBiquadFilter(){return {type:'',frequency:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){}},connect(){},Q:{value:0}};}
  createStereoPanner(){return {pan:{value:0},connect(){}};}
  createBuffer(ch,len){return {getChannelData:()=>new Float32Array(len)};}
};
const ctx=vm.createContext(sandbox);
function fire(type,ev){ev=ev||{};ev.preventDefault=ev.preventDefault||(()=>{});(L[type]||[]).forEach(f=>{try{f(ev);}catch(e){console.log('listener err',type,e.message);}});}
try{
  vm.runInContext(code,ctx,{filename:'cz.js'});
  console.log('BOOT OK');
}catch(e){
  console.log('BOOT FAIL:',e.stack.split('\n').slice(0,4).join(' | '));
  process.exit(1);
}
try{
  vm.runInContext('startGame(0)',ctx);
  console.log('STARTGAME OK — state:',vm.runInContext('game.state',ctx));
}catch(e){
  console.log('START FAIL:',e.stack.split('\n').slice(0,5).join(' | '));
  process.exit(1);
