// All-maps + restart smoke
const fs=require('fs'),vm=require('vm');
const code=fs.readFileSync('/tmp/opencode/cz_script.js','utf8');
function mkCtx(){const grad=()=>({addColorStop(){}});return new Proxy({},{get(t,p){if(p==='createLinearGradient'||p==='createRadialGradient')return grad;if(t[p]!==undefined)return t[p];return()=>{};},set(t,p,v){t[p]=v;return true;}});}
const els={};
function getEl(id){if(els[id])return els[id];const e={id,style:{},textContent:'',innerHTML:'',width:300,height:150,classList:{add(){},remove(){},toggle(){},contains:()=>false},children:[],dataset:{},addEventListener(){},appendChild(c){this.children.push(c);},getContext:()=>mkCtx(),requestPointerLock(){},setPointerCapture(){},onclick:null,oninput:null};els[id]=e;return e;}
const L={};
const sandbox={console,setTimeout,clearTimeout,setInterval,performance,Math,Date,JSON,Object,Array,Uint8Array,Int16Array,Float32Array,Promise,Error,
  document:{getElementById:getEl,createElement:()=>({width:0,height:0,getContext:()=>mkCtx(),style:{}}),addEventListener(){},exitPointerLock(){},pointerLockElement:null,hidden:false,body:{classList:{add(){},remove(){}}}},
  window:null,navigator:{getGamepads:()=>[],maxTouchPoints:0},localStorage:{_d:{},getItem(k){return this._d[k]===undefined?null:this._d[k];},setItem(k,v){this._d[k]=v;},removeItem(k){delete this._d[k];}},
  requestAnimationFrame(cb){sandbox.__raf=cb;return 1;},addEventListener(t,f){(L[t]=L[t]||[]).push(f);}};
sandbox.window=sandbox;sandbox.self=sandbox;sandbox.innerWidth=1280;sandbox.innerHeight=720;
sandbox.AudioContext=class{constructor(){this.currentTime=0;this.state='running';this.destination={};this.sampleRate=44100;}resume(){}
  createGain(){return{gain:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){},linearRampToValueAtTime(){},setTargetAtTime(){}},connect(){},disconnect(){}};}
  createOscillator(){return{type:'',frequency:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){},linearRampToValueAtTime(){}},connect(){},start(){},stop(){}};}
  createBufferSource(){return{buffer:null,connect(){},start(){},stop(){}};}
  createBiquadFilter(){return{type:'',frequency:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){}},connect(){},Q:{value:0}};}
  createStereoPanner(){return{pan:{value:0},connect(){}};}
  createBuffer(c,l){return{getChannelData:()=>new Float32Array(l)};}};
const ctx=vm.createContext(sandbox);
function fire(type,ev){ev=ev||{};ev.preventDefault=ev.preventDefault||(()=>{});(L[type]||[]).forEach(f=>{try{f(ev);}catch(e){console.log('lip err',type,e.message);}});}
function pump(frames){let t=0;
  for(let i=0;i<frames;i++){t+=16;const cb=sandbox.__raf;if(!cb)break;cb(t);
    fire('keyup',{code:'Space'});if(i%6===3)fire('keydown',{code:'Space'});
    fire('keyup',{code:'KeyW'});if(i%4<2)fire('keydown',{code:'KeyW'});}}
vm.runInContext(code,ctx,{filename:'cz.js'});
console.log('BOOT OK');
let fail=false;
for(let mi=0;mi<4;mi++){
  try{
    vm.runInContext('startGame('+mi+')',ctx);
    vm.runInContext('givePoints(6000)',ctx);
    // buy a wall weapon if affordable & a perk
    vm.runInContext('(function(){const b=game.map.buys[0];buyWall(b);buyPerk(game.map.perksA[0]);})()',ctx);
    // sprint/crouch/grenade inputs
    fire('keydown',{code:'ShiftLeft'});fire('keydown',{code:'KeyC'});
    pump(400);
    vm.runInContext('(function(){if(player.hp>0)throwNade();})()',ctx);
    pump(60);
    const st=vm.runInContext('({map:game.map.name,round:game.round,w:curW().w,perks:player.perks.join(","),state:game.state,kills:game.kills})',ctx);
    console.log('MAP'+mi+' OK —',JSON.stringify(st));
    fire('keyup',{code:'ShiftLeft'});fire('keyup',{code:'KeyC'});
  }catch(e){fail=true;console.log('MAP'+mi+' FAIL:',e.stack.split('\n').slice(0,5).join(' | '));}
}
// death + restart round-trip
try{
  vm.runInContext('(function(){player.hp=5;hurtPlayer(200);})()',ctx);
  const s1=vm.runInContext('game.state',ctx);
  vm.runInContext('startGame(0)',ctx);
  const s2=vm.runInContext('({state:game.state,hp:player.hp,round:game.round})',ctx);
  console.log('death/restart —',s1,'→',JSON.stringify(s2),s1==='over'&&s2.state==='play'&&s2.hp>0?'✓ OK':'✗ BAD');
}catch(e){fail=true;console.log('restart FAIL:',e.stack.split('\n').slice(0,4).join(' | '));}
console.log(fail?'✗✗ FAILURES':'✓ ALL MAPS PASSED');
process.exit(fail?1:0);

